window.fiadoForm=function(){
 formModal('Nova Promissória',`<div class="formgrid fiado-form-v101">${f('unit','Unidade','select',['LAGOS','MAGÉ'])}${customerPicker('customer_id','Cliente *')}${f('total','Valor Total (R$) *','number','0')}${f('down_payment','Valor de Entrada (R$) – Opcional','number','0')}<div class="field full"><div class="fiado-calc"><b>Valor a parcelar: <span id="fiadoParcelable">R$ 0,00</span></b><small>Valor total menos entrada</small></div></div>${f('installments','Parcelas *','select',['1x','2x','3x','4x','5x','6x','8x','10x','12x'])}${f('frequency','Frequência de Vencimento *','select',['Mensal (30 dias)','Quinzenal (15 dias)','Semanal (7 dias)'])}${f('due_date','Primeiro Vencimento *','date')}${f('description','Descrição da Obra/Serviço *','textarea','Descreva o serviço ou obra realizada',true)}<div class="field full"><div class="fiado-calc"><b id="fiadoInstallmentPreview">Parcelas serão calculadas automaticamente</b><small>As parcelas são geradas a partir do valor a parcelar.</small></div></div><div class="field full"><label>Produtos</label><div class="product-pick-row"><select class="select" id="fiadoProduct"><option value="">Escolha um produto cadastrado</option></select><button type="button" class="btn" onclick="addFiadoProduct()">＋ Adicionar Produto</button></div><div id="fiadoProducts" class="fiado-products"></div><button type="button" class="btn ghost" style="margin-top:8px" onclick="addManualFiadoProduct()">Adicionar Produto Manual</button></div>${f('notes','Observações','textarea','',true)}</div>`,async()=>{const m=$('#modal'),d=formValues(m.querySelector('#modalForm'));d.installments=Number(String(d.installments||'1x').replace('x',''));d.installment_value=Math.max(0,(Number(d.total||0)-Number(d.down_payment||0))/Math.max(1,d.installments));d.products=readFiadoProducts();d.notes=(d.notes||'')+'\nProdutos: '+JSON.stringify(d.products);if(!d.customer_id)return toast('Selecione um cliente.');if(!d.description)return toast('Preencha a descrição do serviço.');await api('/api/fiado',{method:'POST',body:JSON.stringify(d)});closeModal();toast('Promissória cadastrada');render()});setTimeout(async()=>{wirePickers();const products=await api('/api/inventory?unit='+encodeURIComponent(UNIT));const sel=$('#fiadoProduct');if(sel)sel.innerHTML='<option value="">Escolha um produto cadastrado</option>'+products.map(x=>`<option value="${x.id}" data-name="${esc(x.name)}" data-price="${Number(x.price||0)}">${esc(x.name)} · ${money(x.price)}</option>`).join('');const calc=()=>{const total=Number($('#modalForm [name=total]')?.value||0),down=Number($('#modalForm [name=down_payment]')?.value||0),n=Number(String($('#modalForm [name=installments]')?.value||'1x').replace('x',''));const bal=Math.max(0,total-down),iv=bal/Math.max(1,n);if($('#fiadoParcelable'))$('#fiadoParcelable').textContent=money(bal);if($('#fiadoInstallmentPreview'))$('#fiadoInstallmentPreview').textContent=`${n}x de ${money(iv)}`};$('#modalForm [name=total]')?.addEventListener('input',calc);$('#modalForm [name=down_payment]')?.addEventListener('input',calc);$('#modalForm [name=installments]')?.addEventListener('change',calc);calc()},80)};
function readFiadoProducts(){return [...document.querySelectorAll('#fiadoProducts .fiado-product')].map(x=>({name:x.dataset.name,price:Number(x.dataset.price||0),qty:Number(x.querySelector('input')?.value||1)}))}
window.addFiadoProduct=function(){const sel=$('#fiadoProduct');if(!sel?.value)return toast('Escolha um produto.');const o=sel.options[sel.selectedIndex];const box=$('#fiadoProducts');const d=document.createElement('div');d.className='fiado-product';d.dataset.name=o.dataset.name;d.dataset.price=o.dataset.price;d.innerHTML=`<span>${esc(o.dataset.name)} · ${money(o.dataset.price)}</span><input class="input" type="number" min="1" value="1"><button type="button" class="iconbtn danger" onclick="this.parentElement.remove()">✕</button>`;box.appendChild(d)};
window.addManualFiadoProduct=function(){const name=prompt('Nome do produto');if(!name)return;const price=Number(prompt('Preço do produto','0')||0);const box=$('#fiadoProducts');const d=document.createElement('div');d.className='fiado-product';d.dataset.name=name;d.dataset.price=price;d.innerHTML=`<span>${esc(name)} · ${money(price)}</span><input class="input" type="number" min="1" value="1"><button type="button" class="iconbtn danger" onclick="this.parentElement.remove()">✕</button>`;box.appendChild(d)};
window.fiadoDetails=async id=>{const d=await api('/api/fiado?unit=TODOS'),x=d.find(a=>a.id===id);if(!x)return;const payments=await api('/api/fiado-payments?id='+id).catch(()=>[]);formModal('Detalhes da Promissória #'+id,`<div class="fiado-detail-head"><div><span class="badge ${x.status==='pago'?'g':x.status==='atrasado'?'r':'y'}">${esc(x.status)}</span><h2>${esc(x.customer_name||'Cliente')}</h2><p>${esc(x.customer_phone||'')} · ${esc(x.description||'')}</p></div><div class="fiado-balance"><small>Saldo</small><b>${money(x.balance)}</b></div></div><div class="cards"><div class="metric"><div class="label">TOTAL</div><div class="value">${money(x.total)}</div></div><div class="metric"><div class="label">ENTRADA</div><div class="value green">${money(x.down_payment)}</div></div><div class="metric"><div class="label">PARCELAS</div><div class="value">${x.installments||1}x</div></div><div class="metric"><div class="label">VENCIMENTO</div><div class="value" style="font-size:18px">${esc(x.due_date||'—')}</div></div></div><section class="panel"><h3>Histórico de pagamentos</h3>${payments.length?table(payments,[['paid_at','Data'],['amount','Valor',r=>money(r.amount)],['payment','Forma'],['notes','Observação']]):'<div class="empty">Nenhum pagamento registrado.</div>'}</section>`,async()=>closeModal())};
window.fiadoInterest=function(){formModal('Multas / Juros',`<div class="formgrid">${f('interest','Juros (%)','number','0')}${f('fine','Multa (R$)','number','0')}${f('notes','Regra de cobrança','textarea','Configure a regra que será aplicada aos novos atrasos.',true)}</div>`,async()=>{toast('Regra preparada para cobrança; nenhum título foi alterado.');closeModal()})};
window.fiadoReport=function(){const d=window.__fiadoRows||[];const csv=['ID;Cliente;Total;Entrada;Saldo;Vencimento;Status',...d.map(x=>[x.id,x.customer_name,x.total,x.down_payment,x.balance,x.due_date,x.status].map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';'))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='kvcell-fiado-relatorio.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
window.fiadoPrint=function(){const d=window.__fiadoRows||[];const w=window.open('','_blank');if(!w)return;w.document.write(`<html><head><title>KV CELL • Controle de Fiado</title><style>body{font-family:Arial;padding:30px}h1{color:#111}.k{display:inline-block;margin-right:25px;padding:12px;border:1px solid #ddd;border-radius:8px}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{padding:8px;border:1px solid #ddd;text-align:left}</style></head><body><h1>KV CELL • Controle de Fiado</h1><div class="k">Total: ${money(d.reduce((a,x)=>a+Number(x.total||0),0))}</div><div class="k">A receber: ${money(d.reduce((a,x)=>a+Number(x.balance||0),0))}</div>${fiadoTable(d)}</body></html>`);w.print()};

// ADB / Antivirus / Apple diagnostics — replace the empty placeholder with the supplied reference copy and clear cards.
pages.adb=async()=>{$('#content').innerHTML=analyticsHeader('ADB & Antivírus','Ferramentas de bancada, diagnóstico Android e leitura de dispositivos Apple',`<span class="badge y">CENTRAL DE DIAGNÓSTICO</span>`)+`<div class="adb-hero"><div><span class="badge g">BANCADA</span><h2>Diagnóstico profissional para assistência</h2><p>Conecte o aparelho, siga o preparo indicado e mantenha o fluxo de diagnóstico separado da OS.</p></div><div class="adb-pulse">USB</div></div><div class="adb-grid"><section class="panel adb-card"><div class="adb-icon">🛡</div><h2>Ant Vírus</h2><p>Varredura profissional de apps, permissões, adware e arquivos suspeitos com remoção assistida.</p><button class="btn" onclick="adbConnect('Android','antivirus')">↔ Conectar Android</button><div class="prep"><h3>Como preparar o aparelho</h3><ol><li>Desbloqueie a tela.</li><li>Ative as opções de desenvolvedor quando solicitado.</li><li>Autorize a conexão USB.</li></ol></div><small class="creator">Feito por <b>brunoG7 coder</b></small></section><section class="panel adb-card"><div class="adb-icon">⌘</div><h2>ADB & Diagnóstico Android</h2><p>Terminal real e ferramentas de bancada para leitura, manutenção, recuperação e modos de inicialização.</p><button class="btn" onclick="adbConnect('Android','adb')">↔ Conectar Android</button><div class="prep"><h3>Como preparar o aparelho</h3><ol><li>Use um cabo USB de dados.</li><li>Desbloqueie o aparelho e aceite a autorização RSA/USB.</li><li>Mantenha o aparelho ligado durante a leitura.</li></ol></div><small class="creator">Feito por <b>brunoG7 coder</b></small></section><section class="panel adb-card apple-card"><div class="adb-icon"></div><h2>iPhone / iPad</h2><p>Leitura USB e diagnóstico das informações que o dispositivo Apple expõe ao navegador.</p><button class="btn" onclick="adbConnect('iPhone','apple')">↔ Conectar iPhone</button><div class="apple-note">Conecte o iPhone ou iPad pelo cabo original</div><p class="muted">Desbloqueie a tela e toque em “Confiar neste computador” para liberar a leitura das informações do dispositivo.</p><div id="adbStatus" class="adb-status">Aguardando conexão...</div><small class="creator">Feito por <b>brunoG7 coder</b></small></section></div>`};
window.adbConnect=async(type,mode)=>{const status=$('#adbStatus');if(status)status.textContent='Verificando conexão '+type+'…';try{if(!navigator.usb)throw Error('O navegador não disponibilizou WebUSB nesta sessão.');const dev=await navigator.usb.requestDevice({filters:[]});if(status)status.textContent=`Dispositivo detectado: ${dev.productName||dev.manufacturerName||type}. A leitura depende das permissões USB disponíveis.`;toast('Dispositivo USB detectado')}catch(e){if(status)status.textContent=type==='iPhone'?'Conecte pelo cabo e confirme “Confiar neste computador”.':'Conecte o Android por USB e autorize a depuração quando solicitado.';toast(e.name==='NotFoundError'?'Nenhum dispositivo selecionado.':e.message)}};

// Remove the three requested sidebar tabs: Meu Plano, Catálogo Digital and Serviços e Indicações.
boot=async function(){
 document.body.innerHTML=`<div class="shell v100-shell"><aside class="sidebar"><div class="brand"><div class="logo-wrap"><div class="logo">KV</div></div><div><b>KV CELL</b><small>ULTIMATE SUPREME • V101</small></div></div><div class="nav"><div class="navtitle">PAINEL</div>${['dashboard'].map(nav).join('')}<div class="navtitle">ATENDIMENTO</div>${['services','agenda','quotes','pricing','adb','guarantees','fiado'].map(nav).join('')}<div class="navtitle">CADASTROS</div>${['customers','radar','technicians','purchases','suppliers'].map(nav).join('')}<div class="navtitle">OPERAÇÃO</div>${['inventory','finance','pdv','devices','forgotten'].map(nav).join('')}<div class="navtitle">DIGITAL</div>${['films','community'].map(nav).join('')}<div class="navtitle">SISTEMA</div>${['employees','chat_units','ai','logs','admin','settings'].map(nav).join('')}</div></aside><main class="main"><div class="topbar"><div><b id="crumb">Painel</b><div class="crumb">KV CELL ULTIMATE SUPREME • LAGOS + MAGÉ • V101</div></div><div class="top-actions"><select id="unit" class="select unit"><option>TODOS</option><option>LAGOS</option><option>MAGÉ</option></select><button class="btn ghost" onclick="openSearch()">⌕ Buscar</button><button class="btn ghost" onclick="logout()">Sair</button></div></div><div id="content"></div></main></div><div id="modal" class="modal"></div><div id="toast" class="toast"></div>`;
 $('#unit').value=UNIT;$('#unit').onchange=e=>{UNIT=e.target.value;localStorage.setItem('kv_unit',UNIT);render()};render();
};
